import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../models/address.dart'; import '../providers/address_provider.dart'; import '../providers/cart_provider.dart'; import '../providers/order_provider.dart'; import 'order_detail_screen.dart';
class CheckoutScreen extends StatefulWidget{const CheckoutScreen({super.key});@override State<CheckoutScreen> createState()=>_CheckoutScreenState();}
class _CheckoutScreenState extends State<CheckoutScreen>{final n=TextEditingController(),m=TextEditingController(),h=TextEditingController(),s=TextEditingController(),a=TextEditingController(),p=TextEditingController();bool loading=false;
 @override void dispose(){for(final x in[n,m,h,s,a,p])x.dispose();super.dispose();}
 Future<void> place()async{if([n,m,h,s,a,p].any((x)=>x.text.trim().isEmpty)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Please complete the delivery address.')));return;}setState(()=>loading=true);final cart=context.read<CartProvider>();final addr=Address(name:n.text.trim(),mobile:m.text.trim(),house:h.text.trim(),street:s.text.trim(),area:a.text.trim(),city:'Hyderabad',state:'Telangana',pincode:p.text.trim(),isDefault:true);context.read<AddressProvider>().save(addr);final order=context.read<OrderProvider>().create(cart.items,addr.oneLine,cart.subtotal,cart.delivery);cart.clear();if(!mounted)return;setState(()=>loading=false);Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>OrderDetailScreen(order:order)),(r)=>r.isFirst);}
 @override Widget build(BuildContext c){final cart=c.watch<CartProvider>();return Scaffold(appBar:AppBar(title:const Text('Checkout',style:TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Delivery address',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:12),for(final x in[('Full name',n),('Mobile number',m),('House / Flat',h),('Street',s),('Area',a),('Pincode',p)])Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:x.$2,keyboardType:x.$1=='Mobile number'||x.$1=='Pincode'?TextInputType.phone:TextInputType.text,decoration:InputDecoration(labelText:x.$1))),const SizedBox(height:10),Card(child:const ListTile(leading:Icon(Icons.payments_outlined),title:Text('Cash on Delivery',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('Pay when your order arrives'),trailing:Icon(Icons.check_circle,color:Color(0xff0b7a53)))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[_r('Subtotal',cart.subtotal),_r('Delivery',cart.delivery),const Divider(),_r('Total',cart.total,bold:true)]))),const SizedBox(height:14),SizedBox(height:54,child:FilledButton(onPressed:loading?null:place,child:loading?const CircularProgressIndicator():Text('Place COD Order • ₹${cart.total.round()}')))]));}
 Widget _r(String x,double v,{bool bold=false})=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(children:[Text(x,style:TextStyle(fontWeight:bold?FontWeight.w900:null)),const Spacer(),Text('₹${v.round()}',style:TextStyle(fontWeight:bold?FontWeight.w900:null))]));}
